<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driven;

use Override;
use PDO;
use Civi\Lughauth\Features\OAuth\Profile\Domain\ActiveSession;
use Civi\Lughauth\Features\OAuth\Profile\Domain\Gateway\SessionsGateway;

class SessionsAdapter implements SessionsGateway
{
    public function __construct(
        private readonly PDO $pdo,
    ) {
    }

    #[Override]
    public function listByUser(string $userUid): array
    {
        $now = (new \DateTimeImmutable())->format('Y-m-d H:i:s');
        $stmt = $this->pdo->prepare(
            'SELECT session, client_id, client_name, ip_address, user_agent, last_used_at, expiration, auth_data ' .
            'FROM _oauth_session ' .
            'WHERE expiration > :now ' .
            'ORDER BY last_used_at DESC'
        );
        $stmt->bindValue('now', $now, PDO::PARAM_STR);
        $stmt->execute();

        $sessions = [];
        while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
            $data = (array) json_decode((string) $row['auth_data'], true);
            if (($data['userId'] ?? null) !== $userUid) {
                continue;
            }
            $sessions[] = new ActiveSession(
                sessionId: $row['session'],
                clientId: $row['client_id'],
                clientName: $row['client_name'],
                ipAddress: $row['ip_address'],
                userAgent: $row['user_agent'],
                lastUsedAt: $row['last_used_at'],
                expiration: $row['expiration'],
            );
        }
        return $sessions;
    }

    #[Override]
    public function revoke(string $sessionId): void
    {
        $stmt = $this->pdo->prepare('DELETE FROM _oauth_session WHERE session = :session');
        $stmt->bindValue('session', $sessionId, PDO::PARAM_STR);
        $stmt->execute();
    }
}
